import random
import math
from fractions import Fraction

def is_k_colorable(graph, k):
    n = len(graph)
    colors = [-1] * n

    def dfs(node, color):
        if node in visited:
            return True
        visited.add(node)
        colors[node] = color

        for neighbor in graph[node]:
            if colors[neighbor] == color or not dfs(neighbor, (color + 1) % k):
                return False
        return True

    visited = set()
    for i in range(n):
        if node not in visited:
            if not dfs(i, 0):
                return False
    return True

def generate_k_colorable_graph(n, k):
    graph = [[] for _ in range(n)]
    colors = [random.randint(0, k-1) for _ in range(n)]

    def add_edge(u, v):
        if u != v and (v not in graph[u] or u not in graph[v]):
            graph[u].append(v)
            graph[v].append(u)

    while True:
        for i in range(n):
            for j in range(i+1, n):
                if colors[i] == colors[j]:
                    add_edge(i, j)
        if is_k_colorable(graph, k):
            break
        graph = [[] for _ in range(n)]

    return graph

def minimal_quadratic_residue_representation(graph):
    n = len(graph)
    mqr = 0

    def quadratic_residue(x):
        return x * x % (n + 1)

    for i in range(n):
        for j in range(i+1, n):
            if j in graph[i]:
                mqr += quadratic_residue(j - i)

    return mqr

def communication_complexity_growth_rate(graph, k):
    n = len(graph)
    growth_rate = 0

    def dfs(node, visited):
        nonlocal growth_rate
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                growth_rate += 1
                dfs(neighbor, visited)

    for i in range(n):
        visited = set()
        dfs(i, visited)

    return growth_rate

