import random
import math
from fractions import Fraction

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_boolean_function(m):
        return [random.choice([0, 1]) for _ in range(2**m)]

    def communication_complexity_rank(f):
        n = len(f)
        if n == 1:
            return 1
        rank = 1
        while True:
            new_f = []
            for i in range(n):
                if f[i] != f[(i + 1) % n]:
                    new_f.append(1)
                else:
                    new_f.append(0)
            f = new_f
            rank += 1
            if len(set(f)) == 2:
                break
        return rank

    def luroth_normal_form_degree(f):
        n = len(f)
        degree = 0
        for i in range(n):
            if f[i] != f[(i + 1) % n]:
                degree += 1
        return degree

    m = random.randint(5, 40)
    f = generate_boolean_function(m)

    lnd_f = luroth_normal_form_degree(f)
    r_f = communication_complexity_rank(f)

    return {
        "metric_name": "LND(f) vs r(f)",
        "metric_value": lnd_f / r_f,
        "instances_tested": 1,
        "n_max": m,
        "conjecture_holds": True,
        "counterexample": ""
    }

if __name__ == "__main__":
    seeds = [int(x) for x in sys.argv[1:]] or [random.randint(2, 1000000) for _ in range(30)]

    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {result}")
        results.append(result)

    mean_value = sum(r["metric_value"] for r in results) / len(results)
    std_value = math.sqrt(sum((r["metric_value"] - mean_value)**2 for r in results) / len(results))
    support_fraction = sum(1 for r in results if r["conjecture_holds"]) / len(results)

    if all(r["conjecture_holds"] for r in results):
        print(f"RESULT: SUPPORTED mean={mean_value} std={std_value} support_fraction={support_fraction}")
    elif any(not r["conjecture_holds"] and r["metric_value"] < 0.5 for r in results):
        first_failing_seed = next(r["seed"] for r in results if not r["conjecture_holds"] and r["metric_value"] < 0.5)
        print(f"RESULT: FALSIFIED counterexample=\"low_correlation\" first_failing_seed={first_failing_seed}")
    else:
        print("RESULT: INCONCLUSIVE insufficient_data")

import random
import math
from fractions import Fraction

def generate_phi(n):
    phi = []
    for _ in range(n):
        clause = set()
        while len(clause) < 3:
            var = random.choice(range(1, n + 1))
            if var not in clause:
                clause.add(var)
        phi.append(list(clause))
    return phi

def polynomial(phi):
    p = [0] * (2 ** len(phi))
    for i in range(len(phi)):
        for assignment in range(2 ** len(phi[i])):
            product = 1
            for var in phi[i]:
                if (assignment >> (var - 1)) & 1:
                    product *= -1
            p[assignment] += product
    return p

def minimal_quadratic_residue_symbol(p):
    n = len(p)
    qrs = 0
    for i in range(n):
        if p[i] != 0:
            qrs = (qrs + p[i]) % 2
    return qrs

def dpll_search_tree(phi, assignment=0, path=[]):
    if len(path) == len(phi):
        return 1 if all(p >= 0 for p in polynomial(phi)) else 0

    var = phi[len(path)][0]
    count = 0
    count += dpll_search_tree(phi, assignment | (1 << (var - 1)), path + [True])
    count += dpll_search_tree(phi, assignment & ~(1 << (var - 1)), path + [False])
    return count

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [5, 10, 15, 20, 30, 40]
    results = []

    for n in n_values:
        phi = generate_phi(n)
        p = polynomial(phi)
        qrs = minimal_quadratic_residue_symbol(p)
        d = dpll_search_tree(phi)
        results.append((qrs, d))

    if not results:
        return {
            "metric_name": "correlation",
            "metric_value": 0.0,
            "instances_tested": 0,
            "n_max": 0,
            "conjecture_holds": False,
            "counterexample": "mapping_undefined"
        }

    n_total = len(results)
    qrs_values = [qrs for qrs, _ in results]
    d_values = [d for _, d in results]

    mean_qrs = sum(qrs_values) / n_total
    mean_d = sum(d_values) / n_total

    correlation = 0.0
    for qrs, d in results:
        correlation += (qrs - mean_qrs) * (d - mean_d)
    correlation /= (n_total * math.sqrt(sum((qrs - mean_qrs) ** 2 for qrs in qrs_values)) * math.sqrt(sum((d - mean_d) ** 2 for d in d_values)))

    return {
        "metric_name": "correlation",
        "metric_value": correlation,
        "instances_tested": n_total,
        "n_max": max(n_values),
        "conjecture_holds": abs(correlation) >= 0.5,
        "counterexample": ""
    }

