            return None
        circuit = [[0] * n for _ in range(n)]
        edges = set()
        while len(edges) < d * n // 2:
            u = random.randint(0, n - 1)
            v = random.randint(0, n - 1)
            if u != v and (u, v) not in edges and (v, u) not in edges:
                circuit[u][v] = 1
                circuit[v][u] = 1
                edges.add((u, v))
        return circuit

    def compute_p_adic_hodge_rank(circuit):
        n = len(circuit)
        A = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if circuit[i][j] == 1:
                    A[i][j] = 1
        rank = 0
        for row in A:
            if any(row):
                rank += 1
                for j in range(n):
                    if row[j]:
                        for k in range(n):
                            A[k][j] -= row[k]
        return rank

    def compute_monotone_width(circuit):
        n = len(circuit)
        width = 0
        for i in range(1 << n):
            subset = [j for j in range(n) if (i & (1 << j)) != 0]
            if all(circuit[u][v] == 0 for u in subset for v in subset if u != v):
                width = max(width, len(subset))
        return width

