import random
import math
from fractions import Fraction

def gaussian_elimination(A, b):
    n = len(b)
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(A[j][i]) > abs(A[max_row][i]):
                max_row = j
        A[i], A[max_row] = A[max_row], A[i]
        b[i], b[max_row] = b[max_row], b[i]
        for j in range(i+1, n):
            factor = Fraction(A[j][i], A[i][i])
            for k in range(i, n):
                A[j][k] -= factor * A[i][k]
            b[j] -= factor * b[i]
    x = [0] * n
    for i in range(n-1, -1, -1):
        x[i] = Fraction(b[i], A[i][i])
        for j in range(i-1, -1, -1):
            b[j] -= A[j][i] * x[i]
    return x

def matrix_multiply(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def adjugate_matrix(A):
    n = len(A)
    if n == 1:
        return [[A[0][0]]]
    submatrices = []
    for i in range(n):
        for j in range(n):
            submatrix = [row[:j] + row[j+1:] for row in A[:i] + A[i+1:]]
            submatrices.append(submatrix)
    cofactors = [[(-1)**(i+j) * det(submatrix) for j in range(n)] for i in range(n)]
    return transpose_matrix(cofactors)

def determinant(A):
    n = len(A)
    if n == 1:
        return A[0][0]
    det = 0
    for j in range(n):
        submatrix = [row[:j] + row[j+1:] for row in A[1:]]
        det += (-1)**j * A[0][j] * determinant(submatrix)
    return det

def transpose_matrix(A):
    n = len(A)
    m = len(A[0])
    B = [[0] * n for _ in range(m)]
    for i in range(n):
        for j in range(m):
            B[j][i] = A[i][j]
    return B

def generate_d_regular_graph(d, n):
    if d * n % 2 != 0:
        raise ValueError("d * n must be even")
    G = [[0] * n for _ in range(n)]
    edges = set()
    while len(edges) < d * n // 2:
        u = random.randint(0, n-1)
        v = random.randint(0, n-1)
        if u != v and (u, v) not in edges and (v, u) not in edges:
            G[u][v] = 1
            G[v][u] = 1
            edges.add((u, v))
    return G

def adjacency_matrix_spectral_radius(G):
    n = len(G)
    A = [[G[i][j] for j in range(n)] for i in range(n)]
    eigenvalues = []
    I = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    for _ in range(20):  # Power iteration method
        v = [random.random() for _ in range(n)]
        v = [x / sum(v) for x in v]
        Av = matrix_multiply(A, v)
        lambda_ = max(abs(x) for x in Av)
        eigenvalues.append(lambda_)
    return max(eigenvalues)

def construct_tseitin_formula(G):
    n = len(G)
    clauses = []
    literals = {}
    for i in range(n):
