        A[pivot_row], A[rank] = A[rank], A[pivot_row]
        for k in range(n):
            A[rank][k] /= A[rank][j]
        for i in range(m):
            if i != rank and A[i][j] != 0:
                for k in range(n):
                    A[i][k] -= A[rank][k] * A[i][j]
        rank += 1
    return rank

