    return {
        "metric_name": "min_order_over_monotone_width",
        "metric_value": mean_m / mean_w,
        "instances_tested": len(results),
        "n_max": max(n_values),
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

if __name__ == "__main__":
